# owner: platform
"""Notices telling parents about missed days."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date


def checked_marks(
    student: Student, marks: Iterable[Mark]
) -> List[Mark]:
    found = list(marks)
    owners = {mark.student_id for mark in found}
    if owners - {student.student_id}:
        raise ValueError("marks for another student")
    return found


def notice_text(student: Student, days: List[date]) -> str:
    """Name the student, the count and the dates."""
    if not days:
        raise ValueError("no absences to write about")
    name = f"{student.first_name} {student.last_name}"
    noun = "day" if len(days) == 1 else "days"
    dates = ", ".join(map(date.isoformat, days))
    return f"{name} missed {len(days)} {noun}: {dates}."


def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice for a parent listing a student's absences."""
    found = checked_marks(student, marks)
    return notice_text(student, days_missed(found))
